package com.erp.reimbursement.security; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter {private final JwtService jwt; private final CustomUserDetailsService uds; public JwtAuthenticationFilter(JwtService jwt,CustomUserDetailsService uds){this.jwt=jwt;this.uds=uds;} protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization");String t=null;if(h!=null&&h.startsWith("Bearer ")){t=h.substring(7);}else{String paramToken=req.getParameter("token");if(paramToken!=null&&!paramToken.isBlank()){t=paramToken;}}if(t!=null&&jwt.valid(t)){try{String u=jwt.username(t);UserDetails d=uds.loadUserByUsername(u);SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(d,null,d.getAuthorities()));}catch(Exception ignored){}}chain.doFilter(req,res);}}
